package com.drogaria.backend.controller;
import com.drogaria.backend.dto.PromocaoRequest; import com.drogaria.backend.entity.Promocao; import com.drogaria.backend.service.PromocaoService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/promocao") public class PromocaoController { private final PromocaoService s; public PromocaoController(PromocaoService s){this.s=s;} @GetMapping public List<Promocao> listar(){return s.listar();} @GetMapping("/{id}") public Promocao buscar(@PathVariable Integer id){return s.buscar(id);} @PostMapping public ResponseEntity<Promocao> salvar(@Valid @RequestBody PromocaoRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(s.salvar(r));} @PutMapping("/{id}") public Promocao atualizar(@PathVariable Integer id,@Valid @RequestBody PromocaoRequest r){s.excluir(id);return s.salvar(r);} @DeleteMapping("/{id}") public ResponseEntity<Void> excluir(@PathVariable Integer id){s.excluir(id);return ResponseEntity.noContent().build();} }